export interface PlaceOrderInput {
  tenantId: TenantId;
  customerId: string;
  sku: string;
  quantity: number;
  unitPriceCents: number;
  promotionBps: number;
}

export type PlaceOrderResult =
  | { ok: true; orderId: string; totalCents: number }
  | { ok: false; reason: string };

export class CheckoutService {
  constructor(
    private readonly inventory: Inventory,
    private readonly payments: PaymentGateway,
    private readonly orders: OrderRepository,
    private readonly outbox: Outbox,
    private readonly clock: Clock,
    private readonly ids: IdSource,
  ) {}

  place(input: PlaceOrderInput): PlaceOrderResult {
    const total = price(input);
    const reservationId = this.ids.next('reservation');
    const reservation = this.inventory.reserve({
      id: reservationId,
      sku: input.sku,
      quantity: input.quantity,
      expiresAt: this.clock.now() + 15 * 60_000,
    });
    if (!reservation) return { ok: false, reason: 'insufficient_stock' };

    const paymentId = this.ids.next('payment');
    const charge = this.payments.charge({ paymentId, tenantId: input.tenantId, amountCents: total.totalCents });
    if (!charge.ok) {
      this.inventory.release(reservationId);
      return charge;
    }

    const orderId = this.ids.next('order');
    const eventId = this.ids.next('event');
    this.inventory.commit(reservationId);
    this.orders.save({
      id: orderId,
      tenantId: input.tenantId,
      customerId: input.customerId,
      sku: input.sku,
      quantity: input.quantity,
      totalCents: total.totalCents,
      paymentId,
      reservationId,
      eventId,
      state: 'paid',
    });
    this.outbox.append({ id: eventId, type: 'order.placed', occurredAt: this.clock.now(), payload: { orderId } });
    return { ok: true, orderId, totalCents: total.totalCents };
  }
}

import { Cents, PaymentId } from '../../core/src';
import { ChargeInput, ChargeResult, PaymentAttempt, PaymentGateway, Refund } from './payment';

export class FakePaymentGateway implements PaymentGateway {
  private readonly paymentAttempts: PaymentAttempt[] = [];
  private readonly paymentRefunds: Refund[] = [];
  private nextRejection?: string;

  rejectNext(reason: string): void {
    this.nextRejection = reason;
  }

  charge(input: ChargeInput): ChargeResult {
    if (this.nextRejection) {
      const reason = this.nextRejection;
      this.nextRejection = undefined;
      this.paymentAttempts.push({ ...input, state: 'rejected', reason });
      return { ok: false, reason };
    }
    this.paymentAttempts.push({ ...input, state: 'captured' });
    return { ok: true };
  }

  refund(paymentId: PaymentId, amountCents: Cents): void {
    const payment = this.paymentAttempts.find((attempt) => attempt.paymentId === paymentId);
    if (!payment || payment.state !== 'captured') throw new Error('payment not captured');
    const alreadyRefunded = this.paymentRefunds
      .filter((refund) => refund.paymentId === paymentId)
      .reduce((total, refund) => total + refund.amountCents, 0);
    if (alreadyRefunded + amountCents > payment.amountCents) throw new Error('refund exceeds capture');
    this.paymentRefunds.push({ paymentId, amountCents });
    payment.state = 'refunded';
  }

  attempts(): PaymentAttempt[] {
    return [...this.paymentAttempts];
  }

  refunds(): Refund[] {
    return [...this.paymentRefunds];
  }
}

import { Order } from './order';

export class OrderRepository {
  private readonly orders = new Map<string, Order>();

  save(order: Order): void {
    this.orders.set(order.id, order);
  }

  findForTenant(tenantId: string, orderId: string): Order | undefined {
    const order = this.orders.get(orderId);
    return order?.tenantId === tenantId ? order : undefined;
  }

  all(): Order[] {
    return [...this.orders.values()];
  }
}

